SIDEKIQ_HTTP_JOB_TEMPLATE = """# frozen_string_literal: true
# Auto-generated Sidekiq HTTP Connector Job for ServiceTask: {node_id} ({node_name})

require "net/http"
require "uri"
require "json"

module Jobs
  class {job_class_name}
    include Sidekiq::Job

    ENDPOINT_URL = "{url}"
    HTTP_METHOD = "{method}"
    DEFAULT_HEADERS = {headers_ruby}.freeze

    def perform(context = {{}})
      ctx = context.transform_keys(&:to_sym)
      uri = URI.parse(ENDPOINT_URL)
      http = Net::HTTP.new(uri.host, uri.port)
      http.use_ssl = (uri.scheme == "https")

      request_class = Net::HTTP.const_get(HTTP_METHOD.capitalize)
      request = request_class.new(uri.request_uri, DEFAULT_HEADERS)
{payload_block}
      response = http.request(request)
      parsed_body = JSON.parse(response.body) rescue response.body
{output_assignment}
      ctx
    end
  end
end
"""

